const listUnifiedMessages = `-- name: ListUnifiedMessages :many
WITH ranked AS (
    SELECT m.id, m.account_id, m.mailbox_id, m.uid, m.pop3_uidl, m.modseq, m.message_id_header, m.provider_msg_id, m.dedupe_key, m.in_reply_to, m.references_list, m.thread_id, m.subject, m.from_addr, m.to_addrs, m.cc_addrs, m.bcc_addrs, m.sent_at, m.received_at, m.size, m.flags, m.keywords, m.local_flag, m.preserved_at, m.snippet, m.has_attachments, m.raw_sha256, m.body_state, m.attachments_state, m.created_at, m.updated_at, row_number() OVER (
        PARTITION BY m.account_id, m.dedupe_key
        ORDER BY CASE mb.role
            WHEN 'inbox' THEN 0 WHEN 'custom' THEN 1 WHEN 'junk' THEN 2
            WHEN 'archive' THEN 3 ELSE 4 END,
            m.received_at DESC, m.id DESC
    ) AS rn
    FROM messages m
    JOIN mailboxes mb ON mb.id = m.mailbox_id
    WHERE ($4::uuid IS NULL OR m.account_id = $4::uuid)
      AND ($5::boolean IS NULL OR (NOT ('\Seen' = ANY(m.flags))) = $5::boolean)
      AND ($6::boolean IS NULL OR m.local_flag = $6::boolean)
      AND ($7::boolean = true OR m.preserved_at IS NULL)
      AND ($6::boolean = true OR mb.role NOT IN ('sent', 'drafts', 'trash'))
)
SELECT id, account_id, mailbox_id, uid, pop3_uidl, modseq, message_id_header, provider_msg_id, dedupe_key, in_reply_to, references_list, thread_id, subject, from_addr, to_addrs, cc_addrs, bcc_addrs, sent_at, received_at, size, flags, keywords, local_flag, preserved_at, snippet, has_attachments, raw_sha256, body_state, attachments_state, created_at, updated_at, rn FROM ranked
WHERE rn = 1
  AND ($1::timestamptz IS NULL OR (received_at, id) < ($1::timestamptz, $2::uuid))
ORDER BY received_at DESC, id DESC
LIMIT $3
`

